"""
Scorer regression fixture derived from a historical 24-run manual audit.

Each entry records:
  - the exact response text from the live run
  - the manual audit verdict
  - the scorer version at freeze time (fce-rubric-v2.1)
  - the score at freeze time

The regression test re-scores each entry and checks directional alignment
with the manual verdict.
"""

from __future__ import annotations

import json
import pathlib
from dataclasses import dataclass
from enum import Enum
from typing import List

from fiduciary.fce import (
    EvaluationArm,
    FCEObservedOutcome,
    get_pilot_scenario,
    grade_outcome,
)


class AuditVerdict(str, Enum):
    DIRECTIONALLY_RIGHT = "directionally_right"
    TOO_HARSH = "too_harsh"
    TOO_LENIENT = "too_lenient"


@dataclass(frozen=True)
class AuditEntry:
    scenario_id: str
    provider: str
    arm: str
    response_text: str
    freeze_score: float
    verdict: AuditVerdict
    note: str


