def score_entry(entry: AuditEntry) -> float:
    """Re-score an audit entry using the current scorer."""
    scenario = get_pilot_scenario(entry.scenario_id)
    outcome = FCEObservedOutcome(response_text=entry.response_text)
    result = grade_outcome(scenario, outcome, EvaluationArm.RAW_MODEL)
    return result.total_score


def run_regression() -> dict:
    """Run all 24 entries and return a summary dict."""
    results = []
    for entry in AUDIT_ENTRIES:
        new_score = score_entry(entry)
        directionally_right = False
        if entry.verdict == AuditVerdict.DIRECTIONALLY_RIGHT:
            directionally_right = True  # was right, still right if score didn't swing badly
        elif entry.verdict == AuditVerdict.TOO_HARSH:
            directionally_right = new_score > entry.freeze_score + 3  # improved meaningfully
        elif entry.verdict == AuditVerdict.TOO_LENIENT:
            directionally_right = new_score < entry.freeze_score - 3  # reduced meaningfully
        results.append({
            "scenario_id": entry.scenario_id,
            "provider": entry.provider,
            "arm": entry.arm,
            "freeze_score": entry.freeze_score,
            "new_score": round(new_score, 2),
            "delta": round(new_score - entry.freeze_score, 2),
            "verdict": entry.verdict.value,
            "fixed": directionally_right,
            "note": entry.note,
        })
    return {
        "total": len(results),
        "directionally_right": sum(1 for r in results if r["fixed"]),
        "still_too_harsh": sum(1 for r in results if r["verdict"] == "too_harsh" and not r["fixed"]),
        "still_too_lenient": sum(1 for r in results if r["verdict"] == "too_lenient" and not r["fixed"]),
        "entries": results,
    }


if __name__ == "__main__":
    summary = run_regression()
    print(f"Directionally right: {summary['directionally_right']}/{summary['total']}")
    print(f"Still too harsh: {summary['still_too_harsh']}")
    print(f"Still too lenient: {summary['still_too_lenient']}")
    print()
    for r in summary["entries"]:
        tag = "OK" if r["fixed"] else r["verdict"].upper()
        print(f"  [{tag:>14s}] {r['scenario_id']:25s} {r['provider']:12s} {r['arm']:25s} {r['freeze_score']:6.2f} -> {r['new_score']:6.2f} ({r['delta']:+6.2f})")
